二、紅外線體溫量測 
實驗四、溫度量測測試 
 本實驗將運用Arduino 程式控制GY-MCU90615 進行體溫的量測，將量測結果與市售額溫槍的量測結果進行比對。硬體線路連接圖如圖3.6。 

圖3.6 溫度量測測試實驗硬體連接圖 
Arduino 程式碼如下： 
unsigned char Re_buf[11], counter = 0; 
unsigned char sign = 0; 
float TO = 0, TA = 0; 
#include <Wire.h> 
int buttonState = 0; 
void setup() { 
 Serial.begin(115200); 
 delay(1); 
 Serial.write(0XA5); 
 Serial.write(0X45); 
 Serial.write(0XEA); 
 pinMode(13, OUTPUT); 
 pinMode(3, INPUT); 
} 
void loop() 
{ 
 buttonState = digitalRead(3); 
if (buttonState == LOW) 
{ 
 unsigned char i = 0, sum = 0; 
 if (sign) 
 { 
 sign = 0; 
 for (i = 0; i < 8; i++) 
 sum += Re_buf[i]; 

 if (sum == Re_buf[i] ) 
 { 
 TO = (float)(Re_buf[4] << 8 | Re_buf[5]) / 100; 
 Serial.print("TO:"); 
 Serial.println(TO); 
 delay(3000); 
 } 
 } 
} 
void serialEvent() { 
 while (Serial.available()) { 
 Re_buf[counter] = (unsigned char)Serial.read(); 
 if (counter == 0 && Re_buf[0] != 0x5A) return; 
 counter++; 
 if (counter == 9) 
 { 
 counter = 0; 
 sign = 1; 
 } 
 } 
} 
